import {openingHtml,openingCss} from './opening-scene.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const C=['#f6aac8','#a7def2','#bba7ee','#ffe66c','#cbe980'];
function svg(s,cls=''){return `<svg class="${cls}" viewBox="0 0 600 430" aria-hidden="true">${s}</svg>`;}
const line=(a,b,c,d,w=5)=>`<path d="M${a} ${b}L${c} ${d}" fill="none" stroke="currentColor" stroke-width="${w}" stroke-linecap="round"/>`;
const box=(x,y,w,h,color,rx=18)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${color}" stroke="currentColor" stroke-width="5"/>`;
const circ=(x,y,r,color)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}" stroke="currentColor" stroke-width="5"/>`;
function icon(type,x=0,y=0,s=1){let p='';if(type==='create')p=box(12,12,155,110,'#fff')+line(12,45,167,45)+`<path d="M38 12l18 33m26-33l18 33m26-33l18 33" stroke="currentColor" stroke-width="9"/>`+`<path d="M44 90l24-25 28 24 27-20 22 34H43z" fill="#f6aac8" stroke="currentColor" stroke-width="4"/>`;else if(type==='publish')p=box(12,12,155,110,'#fff')+line(12,46,167,46)+[0,1,2,3,4,5].map((v)=>box(28+(v%3)*43,60+Math.floor(v/3)*29,27,20,C[v%5],3)).join('');else if(type==='engage')p=box(12,12,155,95,'#fff')+`<path d="M45 107l-9 28 45-28" fill="#fff" stroke="currentColor" stroke-width="5"/>`+[0,1,2].map(v=>circ(52+v*40,58,8,C[v])).join('');else if(type==='monetize')p=box(10,20,160,95,'#fff')+`<path d="M35 75l28-25 30 21 43-31m-25 0h25v25" fill="none" stroke="currentColor" stroke-width="7"/>`;else if(type==='web')p=box(12,12,155,110,'#fff')+line(12,44,167,44)+circ(90,84,25,'#a7def2')+line(65,84,115,84,3)+line(90,60,90,108,3);else if(type==='server')p=[0,1,2].map(v=>box(12,12+v*42,155,33,'#fff',6)+circ(145,29+v*42,4,C[v])).join('');else p=circ(90,65,48,'#fff')+line(42,65,138,65)+line(90,17,90,113);return `<g transform="translate(${x} ${y}) scale(${s})">${p}</g>`;}
function iconArt(type){return `<svg viewBox="0 0 185 155" aria-hidden="true">${icon(type)}</svg>`;}
function card({tag,title,copy='',x,y,w,h,color=C[0],i=0,art=''}){return `<section class="d-card" data-block="${i}" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px;--card:${color}"><span class="d-tag">${esc(tag)}</span><h2>${esc(title)}</h2>${copy?`<p>${esc(copy)}</p>`:''}${art?`<div class="d-mini">${art}</div>`:''}<span class="d-word-mark" data-mark="${i}"></span></section>`;}
function flow(words,cls=''){return `<div class="d-flow ${cls}">${words.map((s,i)=>`<span data-flow="${i}">${esc(s)}</span>${i<words.length-1?'<b>→</b>':''}`).join('')}</div>`;}
function router(){const nodes=[['创作',110,90,'create'],['分发',470,90,'publish'],['互动',470,335,'engage'],['合作',110,335,'monetize']];return svg(`<path d="M180 90h220q65 0 65 100v90q0 55-70 55H180q-70 0-70-70v-90q0-85 70-85z" fill="none" stroke="#171717" stroke-width="10" stroke-dasharray="16 10"/>${nodes.map(([t,x,y,k],i)=>`<g data-route="${i}">${circ(x,y,77,C[i])}${icon(k,x-45,y-46,.52)}<text x="${x}" y="${y+57}" text-anchor="middle" font-size="26" font-weight="800">${t}</text></g>`).join('')}${circ(294,212,97,'#fff')}${circ(294,212,78,'#a7def2')}<text x="294" y="206" text-anchor="middle" font-size="33" font-weight="900">AiToEarn</text><text x="294" y="246" text-anchor="middle" font-size="25" font-weight="700">内容协作</text><g data-content-token transform="translate(0 -76)">${box(276,192,38,47,'#ffe66c',5)}${line(284,205,306,205,3)}${line(284,218,306,218,3)}</g>`,'d-router');}
function thumbArt(kind){if(kind==='prompt')return svg(`${icon('create',60,100,1.6)}<path d="M390 160l35-28 48 20-4 77-72 8-31-26z" fill="#f6aac8" stroke="currentColor" stroke-width="5"/><path d="M402 143l2-33 26 24m28 3l29-26-9 46" fill="#f6aac8" stroke="currentColor" stroke-width="5"/>${circ(421,170,6,'#171717')}${circ(451,170,6,'#171717')}<text x="300" y="355" text-anchor="middle" font-size="48" font-weight="800">橘猫 · 3D动画</text>`);if(kind==='models')return svg(`${box(75,70,450,120,'#fff')}${box(75,225,450,120,'#fff')}<text x="300" y="149" text-anchor="middle" font-size="53" font-weight="800">图像模型</text><text x="300" y="304" text-anchor="middle" font-size="53" font-weight="800">视频模型</text>`);return svg(`${box(80,70,200,270,'#fff')}${box(335,130,180,210,'#fff')}${line(110,128,250,128)}${line(110,170,245,170)}${line(110,212,224,212)}<path d="M390 197l66 42-66 42z" fill="#f6aac8" stroke="currentColor" stroke-width="5"/><text x="300" y="400" text-anchor="middle" font-size="48" font-weight="800">草稿待审核</text>`);}

export {iconArt,router,thumbArt};
